mapper.select:
SELECT  FROM delivery
WHERE event_id = #{eventId} AND tenant_id = #{tenantId}
ORDER BY id

mapper.update:
UPDATE delivery
SET status = 'SUCCEEDED', lease_until = NULL, last_status_code = #{statusCode}, last_error = NULL
WHERE id = #{id} AND status = 'IN_FLIGHT' AND attempts = #{attempts}

UPDATE delivery
SET status = 'PENDING', lease_until = NULL,
    next_attempt_at = DATE_ADD(NOW(3), INTERVAL #{delayMs} * 1000 MICROSECOND),
    last_status_code = #{statusCode}, last_error = #{error}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND attempts = #{attempts}

UPDATE delivery
SET status = 'DEAD', lease_until = NULL, last_status_code = #{statusCode}, last_error = #{error}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND attempts = #{attempts}
